INSERT INTO `visual_chart`(`id`, `name`, `dashboard_id`, `group_id`, `span`, `height`, `update_by`, `update_at`, `type`, `unit`, `weight`, `param`, `pid`, `build_in`, `remark`, `seq`, `var_type`, `var_id`, `x`, `y`, `datasource`) VALUES (308, 'Consul Runtime Gc Pause', @OverviewId + 17, 0, 6, 3, 1, '2023-05-17 07:35:15', 'area', 29, 5, '{\"stack\":0,\"thresholds\":[{\"color\":\"#1df2b5\"}],\"thresholdShow\":true,\"visibility\":{\"result\":\"show\",\"varName\":\"\",\"varValue\":\"\",\"operator\":\"equal\"},\"legend\":{\"values\":[],\"show\":true,\"placement\":\"bottom\"},\"enable\":{\"thresholds\":false,\"visibility\":false,\"legend\":true,\"valueMapping\":false},\"showHeader\":1,\"link\":\"\",\"valueMapping\":[],\"nullType\":\"null\"}', NULL, '0', 'GC pause is a \"stop-the-world\" event, meaning that all runtime threads are blocked until GC completes. Normally these pauses last only a few nanoseconds. But if memory usage is high, the Go runtime may GC so frequently that it starts to slow down Consul.', '2d155466-7284-4fe1-8c8e-0c087e36a965', NULL, NULL, 0, 2, 'metrics');
INSERT INTO `visual_chart`(`id`, `name`, `dashboard_id`, `group_id`, `span`, `height`, `update_by`, `update_at`, `type`, `unit`, `weight`, `param`, `pid`, `build_in`, `remark`, `seq`, `var_type`, `var_id`, `x`, `y`, `datasource`) VALUES (309, 'Consul Raft State Candidate', @OverviewId + 17, 0, 6, 3, 1, '2023-05-17 07:35:15', 'area', 2, 6, '{\"stack\":0,\"thresholds\":[{\"color\":\"#d34aa5\"}],\"thresholdShow\":true,\"visibility\":{\"result\":\"show\",\"varName\":\"\",\"varValue\":\"\",\"operator\":\"equal\"},\"legend\":{\"values\":[],\"show\":true,\"placement\":\"bottom\"},\"enable\":{\"thresholds\":false,\"visibility\":false,\"legend\":true,\"valueMapping\":false},\"showHeader\":1,\"link\":\"\",\"valueMapping\":[],\"nullType\":\"null\"}', NULL, '0', 'consul.raft.state.candidate = this increments whenever a Consul server starts an election.  candidate == 0. Deviations from 0 might indicate flapping leadership.\n\nconsul.serf.member.join	This increments when an agent joins the cluster. If an agent flapped', '2d155466-7284-4fe1-8c8e-0c087e36a965', NULL, NULL, 6, 2, 'metrics');
